using System.Reflection;using System.Text;using System.Text.Json;using Jellyfin.Plugin.Randomizer.Configuration;using Microsoft.AspNetCore.Builder;using Microsoft.AspNetCore.Hosting;using Microsoft.AspNetCore.Http;namespace Jellyfin.Plugin.Randomizer;public sealed class WebInjectionStartupFilter:IStartupFilter{public Action<IApplicationBuilder> Configure(Action<IApplicationBuilder> next)=>app=>{app.Use(async(c,n)=>{if(Plugin.Instance?.Configuration.Enabled!=true||!IsIndex(c)){await n();return;}var original=c.Response.Body;await using var buffer=new MemoryStream();c.Response.Body=buffer;try{await n();buffer.Position=0;using var ms=new MemoryStream();await buffer.CopyToAsync(ms);var bytes=ms.ToArray();if(c.Response.StatusCode==200&&bytes.Length>0){var html=Encoding.UTF8.GetString(bytes);if(!html.Contains("data-jellyfin-randomizer-injected",StringComparison.Ordinal)){html=Inject(html,Plugin.Instance.Configuration);bytes=Encoding.UTF8.GetBytes(html);c.Response.ContentLength=bytes.Length;c.Response.Headers.Remove("ETag");}}c.Response.Body=original;await original.WriteAsync(bytes);}finally{c.Response.Body=original;}});next(app);};static bool IsIndex(HttpContext c){if(!HttpMethods.IsGet(c.Request.Method))return false;var p=c.Request.Path.Value?.TrimEnd('/');return p?.Equals("/web",StringComparison.OrdinalIgnoreCase)==true||p?.Equals("/web/index.html",StringComparison.OrdinalIgnoreCase)==true;}static string Inject(string html,PluginConfiguration c){var a=Assembly.GetExecutingAssembly();var js=Read(a,".Web.randomizer.js");var css=Read(a,".Web.randomizer.css");var cfg=JsonSerializer.Serialize(new{animationEnabled=c.AnimationEnabled,animationDurationMs=c.AnimationDurationMs,defaultEpisodeStrategy=c.DefaultEpisodeStrategy,defaultWatchedFilter=c.DefaultWatchedFilter,historySize=c.HistorySize});var payload="<style data-jellyfin-randomizer-injected>"+css+"</style><script data-jellyfin-randomizer-injected>window.JellyfinRandomizerConfig="+cfg+"</script><script data-jellyfin-randomizer-injected>"+js+"</script>";var i=html.IndexOf("</head>",StringComparison.OrdinalIgnoreCase);return i>=0?html.Insert(i,payload):html+payload;}static string Read(Assembly a,string suffix){var n=a.GetManifestResourceNames().FirstOrDefault(x=>x.EndsWith(suffix,StringComparison.Ordinal));if(n==null)return"";using var s=a.GetManifestResourceStream(n)!;using var r=new StreamReader(s,Encoding.UTF8);return r.ReadToEnd();}}